  if (numbers.length < 2) return [];

  final sorted = List<double>.from(numbers)..sort();
  int left = 0;
  int right = 1;

  while (right + 1 < sorted.length && 
         (sorted[right] - sorted[left]) > (sorted[right + 1] - sorted[right])) {
    left++;
    right++;
  }

  double minDiff = sorted[right] - sorted[left];
  for (int i = 0; i < sorted.length - 1; i++) {
    final diff = sorted[i + 1] - sorted[i];
    if (diff < minDiff) {
