List<int> maximum(List<int> arr, int k) {
  if (arr.length <= k) return List.from(arr);

  var maxHeap = <int>[];
  for (var i in arr.take(k)) {
    insertIntoMaxHeap(maxHeap, i);
  }

  for (var j in arr.skip(k)) {
    if (j > peekFromMaxHeap(maxHeap)) {
      removeTopElementFromMaxHeap(maxHeap);
      insertIntoMaxHeap(maxHeap, j);
    }
  }

  var sortedStack = [];
  while (maxHeap.isNotEmpty) {
    pushToSortedStack(sortedStack, popFromMaxHeap(maxHeap));
  }

  final result = <int>[];
  for (var topOfStack in sortedStack.reversed) {
    result.add(topOfStack);
  }
  return result;
}

void insertIntoMaxHeap(List<int> heap, int element) {
  heap.add(element);
  _bubbleUp(heap, heap.length - 1);
}

int peekFromMaxHeap(List<int> heap) => heap[0];

void removeTopElementFromMaxHeap(List<int> heap) {
  if (heap.isEmpty) return;
  swapElementsInMaxHeap(heap, 0, heap.length - 1);
  heap.removeLast();
  _bubbleDown(heap, 0);
}

int popFromMaxHeap(List<int> heap) {
  if (heap.isEmpty) throw Exception("Heap is empty");
  int top = heap[0];
  swapElementsInMaxHeap(heap, 0, heap.length - 1);
  heap.removeLast();
  _bubbleDown(heap, 0);
  return top;
}

void _bubbleUp(List<int> heap, int index) {
  while (index > 0 && heap[index] > heap[(index - 1) ~/ 2]) {
    swapElementsInMaxHeap(heap, index, (index - 1) ~/ 2);
    index = (index - 1) ~/ 2;
  }
}

void _bubbleDown(List<int> heap, int index) {
  int largestIndex = index;
  int leftChild = 2 * index + 1;
  int rightChild = 2 * index + 2;

  if (leftChild < heap.length && heap[leftChild] > heap[largestIndex]) {
    largestIndex = leftChild;
  }

  if (rightChild < heap.length && heap[rightChild] > heap[largestIndex]) {
    largestIndex = rightChild;
  }

  if (largestIndex != index) {
    swapElementsInMaxHeap(heap, index, largestIndex);
    _bubbleDown(heap, largestIndex);
  }
}

void swapElementsInMaxHeap(List<int> heap, int firstIndex, int secondIndex) {
  var temp = heap[firstIndex];
  heap[firstIndex] = heap[secondIndex];
  heap[secondIndex] = temp;
}

void pushToSortedStack(List<int> stack, int element) {
  if (stack.isEmpty || element >= stack.last) {
    stack.add(element);
  } else {
    int idx = stack.indexOf(stack.firstWhere((e) => e > element), orElse: () => stack.length);
    stack.insert(idx, element);
  }
}

