class _GrowableList<T> extends ListBase<T> {
  T? _elementData[];
  int _length = 0;
  int _capacity = 0;

  _GrowableList(int initialCapacity) : this._() {
    _init(initialCapacity);
  }

  void add(T element) {
    _ensureCapacity(_length + 1);
    _elementData[_length++] = element;
  }

  @override
  operator []=(int index, T value) {
    if (_elementData == null || _elementData[index] == null) {
      throw RangeError(index);
    }
    _elementData[index] = value;
  }

  void _init(int capacity) {
    _elementData = new T[capacity];
    this._capacity = capacity;
  }

  void _ensureCapacity(int desiredSize) {
    while (_capacity <= desiredSize) {
      _growToNextCapacity();
    }
  }

  void _growToNextCapacity() {
    if (_elementData == null) {
      _init(8);
      return;
    }
    int newSize = _capacity * 2 + 1;
    T newData[newSize];
    for (int i = 0; i < _capacity; i++) {
      newData[i] = _elementData[i];
    }
    _elementData = newData;
    _capacity = newSize;
  }
}

