String findMax(List<String> words) {
  if (words.isEmpty) return '';


  List<int> lengths = [];
  for (var word in words) {
    int len = word.length;

    bool isPalindrome = true;
    for (int i = 0, j = word.length - 1; i < j; i++, j--) {
      if (word[i] != word[j]) {
        isPalindrome = false;
        break;
      }
    }
    if (!isPalindrome && len > 3) {
      len--; 
    }
    lengths.add(len);
  }



  var sortedLengths = [...lengths].sort((a, b) => a.compareTo(b));
  var maxLength = sortedLengths.last;

  var maxWords = words.where((word) {
    int currentLen = word.length;
    bool currIsPalin = true;
    for (int i = 0, j = word.length - 1; i < j; i++, j--) {
      if (word[i] != word[j]) {
        currIsPalin = false;
        break;
      }
    }
    if (!currIsPalin && currentLen > 3) {
      currentLen--;
    }
    return currentLen == maxLength;
  });


  String result = '';
  if (maxWords.isNotEmpty) {
    String candidate = '';
    for (var w in maxWords) {

      if (w.length >= candidate.length) {
        candidate = w;
      } else if (candidate.isNotEmpty && candidate[0] < w[0]) {
