}

String findMax(List<String> words) {
  List<int> counts = [];

  void addCount(String word, int count) {
    if (counts.isEmpty || count > counts[counts.length - 1]) {
      counts.add(count);
    } else {
      return;
    }
    for (int i = 0; i < counts.length; i++) {
      if (words[i] == word && counts[i] >= count) {
        counts[i] = count;
        break;
      }
    }
  }

  String clean(String s) => s.replaceAllMapped(RegExp(r"[^a-zA-Z]"), (_) => '');

  int totalLetters(int n) {
    final digits = '0123456789';
    int sum = 0;
    while (n > 0) {
      sum += digits.indexOf(n % 10);
      n ~/= 10;
    }
    return sum;
  }

  bool isPalindrome(String s) {
    final cleaned = s.toLowerCase().replaceAll(' ', '').toLowerCase();
    final reversed = cleaned.split('').reversed.join();
    return cleaned == reversed;
  }

  bool containsVowel(String s) {
    const vowels = {'a', 'e', 'i', 'o', 'u'};
    for (var c in s.split('')) {
      if (vowels.contains(c)) return true;
    }
    return false;
  }

  for (final w in words) {
    final cw = clean(w);
    if (cw.isNotEmpty) {
      if (isPalindrome(cw)) {
        addCount(cw, cw.length * 2 + totalLetters(cw.length));
      } else {
        addCount(cw, cw.length + totalLetters(cw.length));
      }
      if (!containsVowel(cw)) {
        addCount(cw, cw.length * 2);
      }
    }
  }

  if (counts.isEmpty) return '';
  var bestWord = words[0];
  var bestScore = counts[0];
  for (int i = 1; i < counts.length; i++) {
    if (counts[i] > bestScore) {
      bestScore = counts[i];
      bestWord = words[i];
    }
  }
  return bestWord;
}

